mapper.select:
SELECT id, stocks_id, stocks_shortname, bar_start_time, reference_price, ma1d, ma7d, ma30d, zscore1d, zscore7d, zscore30d, return6h, return1d, return7d, return14d, low30d, high30d, width30d, position30, pct_above_30d_low, pct_below_30d_high, strategy_ready, data_quality_reason, feature_version, deleted, create_time, update_time FROM ( SELECT f.*, ROW_NUMBER() OVER ( PARTITION BY f.stocks_id ORDER BY f.bar_start_time DESC, f.id DESC ) AS row_num FROM torn_stock_strategy_feature_15m f WHERE f.deleted = 0 AND f.bar_start_time <= #{maxBarStartTime} AND f.feature_version = #{featureVersion} AND f.stocks_id IN
#{id}
) latest WHERE row_num = 1 ORDER BY stocks_id
